function peakMb(cfg) {
  // cfg: { sharedBuffersMb, backends, workMemMb, opsPerBackend, perBackendOverheadMb }
  const perBackend = cfg.workMemMb + cfg.perBackendOverheadMb; // BUG: work_mem charged once
  return cfg.sharedBuffersMb + cfg.backends * perBackend;
}

